INSERT INTO merchant_category(merchant_id,category_id) SELECT m.id,c.id FROM (VALUES('00000000-0000-4000-8000-000000000101','restaurants'),('00000000-0000-4000-8000-000000000102','convenience'),('00000000-0000-4000-8000-000000000103','grocery'),('00000000-0000-4000-8000-000000000104','local-shops'),('00000000-0000-4000-8000-000000000105','flowers-gifts')) x(merchant_id,slug) JOIN merchant m ON m.id=x.merchant_id::uuid JOIN marketplace_category c ON c.slug=x.slug ON CONFLICT DO NOTHING;
