INSERT INTO catalog_product(id,tenant_id,catalog_id,category_id,name,slug,description,price_cents,sku,upc,inventory_count,available,image_ref) SELECT gen_random_uuid(),'00000000-0000-4000-8000-000000000002',v.catalog_id::uuid,v.category_id::uuid,format('%s %s',v.prefix,g),lower(regexp_replace(format('%s-%s',v.prefix,g),'[^a-zA-Z0-9]+','-','g')),format('Demo %s item %s for the Me2U demonstration market.',v.prefix,g),v.base_price+(g*37),format('%s-%03s',upper(substr(v.prefix,1,3)),g),format('000000000%03s',g),100,true,'https://images.unsplash.com/photo-1542838132-92c53300491e?w=800' FROM (VALUES ('00000000-0000-4000-8000-000000000501','00000000-0000-4000-8000-000000000601','Harbor Plate',1299,20),('00000000-0000-4000-8000-000000000502','00000000-0000-4000-8000-000000000602','Corner Cart Item',299,75),('00000000-0000-4000-8000-000000000503','00000000-0000-4000-8000-000000000603','Greenline Pantry',399,50),('00000000-0000-4000-8000-000000000504','00000000-0000-4000-8000-000000000604','Northstar Find',899,25),('00000000-0000-4000-8000-000000000505','00000000-0000-4000-8000-000000000605','Petal Post Gift',1599,15)) v(catalog_id,category_id,prefix,base_price,item_count) CROSS JOIN LATERAL generate_series(1,v.item_count) g ON CONFLICT DO NOTHING;
